WITH scored AS (SELECT *, LEAD(stock_qty) OVER (PARTITION BY category, brand ORDER BY cost, id) AS next_stock_qty, LAG(stock_qty) OVER (PARTITION BY category, brand ORDER BY cost, id) AS prev_stock_qty, LEAD(cost) OVER (PARTITION BY category, brand ORDER BY cost, id) AS next_cost, ROW_NUMBER() OVER (PARTITION BY category, brand ORDER BY cost, id) AS event_seq, SUM(stock_qty) OVER (PARTITION BY brand ORDER BY launch_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_stock_qty FROM products) SELECT DATE_TRUNC('YEAR', launch_date) AS year_start, supplier_id, COUNT(DISTINCT category) AS distinct_categories, MIN(price) AS min_price, COUNT(DISTINCT category) AS distinct_categories_2 FROM scored GROUP BY year_start, supplier_id ORDER BY distinct_categories DESC NULLS FIRST;
